"""Envato site flow adapted from Rambla Tools (2026-09-29)."""
SCRIPT = '(async (projectName) => {\nfunction scaricaEnvato(nome, vecchia) {\n  const attesa = ms => new Promise(r => setTimeout(r, ms));\n  const vis = e => { if (!e) return false; const r = e.getBoundingClientRect(); return r.width > 0 && r.height > 0; };\n  const primo = s => [...document.querySelectorAll(s)].find(vis) || null;\n  const aspetta = async (fn, ms) => { const fine = Date.now() + ms; for (;;) { const v = fn(); if (v) return v; if (Date.now() > fine) return null; await attesa(250); } };\n  const norm = s => String(s || \'\').normalize(\'NFC\').replace(/\\s+/g, \' \').trim().toLowerCase();\n  const clic = el => { try { el.scrollIntoView({ block: \'center\' }); } catch (e) { } el.click(); };\n  const scrivi = (el, v) => {\n    const d = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, \'value\');\n    el.focus(); d.set.call(el, v);\n    el.dispatchEvent(new Event(\'input\', { bubbles: true })); el.dispatchEvent(new Event(\'change\', { bubbles: true }));\n  };\n  const NUOVO = \'[data-cy="idp-download-button"], [data-cy="idp-header-download-button"]\';\n  const VECCHIO_DL = \'[data-testid="button-download"], [data-testid="button-download-for-free"], [data-testid="action-bar-button-download"]\';\n  const VECCHIO = VECCHIO_DL + \', [data-testid="subscribed-onboarding-modal-cta"]\';\n\n  // come il sito: il router della pagina chiama la route "download" e restituisce l\'indirizzo del file\n  const perRouter = b => new Promise(ris => {\n    const R = window.__reactRouterDataRouter;\n    const itemUuid = b.getAttribute(\'data-analytics-item_id\'), itemType = b.getAttribute(\'data-analytics-item_type\');\n    if (!R || typeof R.fetch !== \'function\' || typeof R.subscribe !== \'function\' || !itemUuid || !itemType) return ris(null);\n    const p = new URLSearchParams();\n    p.set(\'itemUuid\', itemUuid);\n    p.set(\'itemType\', itemType);\n    const formato = b.getAttribute(\'data-analytics-asset_uuid\');\n    if (formato) p.set(\'assetUuid\', formato);\n    if (nome) p.set(\'projectName\', nome);\n    const chiave = \'rambla-download-\' + Date.now();\n    let visto = false, finito = false, stop = () => { };\n    const fine = v => { if (finito) return; finito = true; clearTimeout(t); try { stop(); } catch (e) { } ris(v); };\n    const t = setTimeout(() => fine(visto ? { lento: true } : null), 40000);\n    stop = R.subscribe(st => {\n      const f = st.fetchers && st.fetchers.get(chiave);\n      if (f) { visto = true; if (f.state === \'idle\') fine({ dati: f.data }); }\n      else if (visto) fine({ dati: null });           // richiesta finita male o dirottata (es. accesso scaduto)\n    });\n    try {\n      const m = (R.state && R.state.matches) || [];\n      const pr = R.fetch(chiave, m.length ? m[m.length - 1].route.id : \'root\', \'/download?\' + p.toString());\n      if (pr && typeof pr.catch === \'function\') pr.catch(() => fine(null));\n    } catch (e) { fine(null); }\n  });\n\n  return (async () => {\n    const b0 = await aspetta(() => primo(NUOVO) || primo(VECCHIO), 20000);\n    if (!b0) return { ok: false, errore: \'la pagina dell\\\'elemento non mostra il bottone Download\' };\n\n    // pagina vecchia (elements.envato.com)\n    if (!b0.matches(NUOVO)) {\n      if (b0.matches(\'[data-testid="subscribed-onboarding-modal-cta"]\')) { clic(b0); await attesa(1200); }\n      const d = await aspetta(() => primo(VECCHIO_DL), 8000);\n      if (!d) return { ok: false, errore: \'non trovo il bottone Download\' };\n      clic(d);\n      const r = await vecchia(nome);\n      if (r && r.come) r.come = \'pagina vecchia, \' + r.come;\n      return r;\n    }\n\n    // app nuova. Senza abbonamento lo stesso bottone porta ai prezzi (link) o alla finestra "Subscribe"\n    const b = primo(\'[data-cy="idp-download-button"]\') || b0;\n    if (b.tagName === \'A\' && /pricing|subscri|plans?\\b/i.test(b.getAttribute(\'href\') || \'\')) return { ok: false, abbonamento: true, errore: \'serve un abbonamento attivo\' };\n    // il router della pagina arriva quando React ha finito di agganciarla: prima un clic di riserva non farebbe niente\n    await aspetta(() => window.__reactRouterDataRouter && typeof window.__reactRouterDataRouter.fetch === \'function\', 8000);\n    const r = await perRouter(b);\n    if (r && r.dati && r.dati.downloadUrl) {\n      const fr = document.createElement(\'iframe\');\n      fr.style.display = \'none\';\n      fr.src = r.dati.downloadUrl;\n      document.body.appendChild(fr);\n      // (il download non dipende dall\'iframe; lo si toglie tardi: un file grande puo\' metterci a partire)\n      setTimeout(() => { try { fr.remove(); } catch (e) { } }, 10 * 60000);\n      return { ok: true, come: nome ? \'licenza "\' + nome + \'"\' : \'licenza standard\' };\n    }\n    if (r && r.dati && r.dati.error) {\n      const limite = r.dati.errorCode === \'fair_use_limit_exceeded\';\n      if (/subscri|entitle|upgrade/i.test(String(r.dati.errorCode || \'\') + \' \' + r.dati.error)) return { ok: false, abbonamento: true, errore: String(r.dati.error) };\n      return { ok: false, sito: true, definitivo: limite, errore: limite ? \'hai raggiunto il limite di download di Envato: riprova più tardi\' : \'Envato risponde «\' + String(r.dati.error).slice(0, 200) + \'»\' };\n    }\n    if (r && r.lento) return { ok: false, errore: \'Envato non ha preparato il file in tempo\' };\n\n    // riserva: come farebbe una persona\n    clic(b);\n    const pop = await aspetta(() => primo(\'[data-cy="license-popup"]\') || primo(\'[data-cy="access-modal"]\'), 4000);\n    if (!pop) return { ok: true, come: \'clic su Download (licenza secondo la preferenza dell\\\'account Envato)\' };\n    if (pop.matches(\'[data-cy="access-modal"]\')) return { ok: false, abbonamento: true, errore: \'serve un abbonamento attivo\' };\n    const cerca = pop.querySelector(\'input\');\n    if (cerca && nome) { scrivi(cerca, nome); await attesa(700); }\n    const crea = primo(\'[data-cy="license-popup-create-button"]\');   // c\'e\' solo se il nome non esiste ancora\n    if (crea) {\n      if (crea.disabled) return { ok: false, errore: \'Envato non lascia creare la licenza "\' + nome + \'"\' };\n      clic(crea);\n      return { ok: true, come: \'licenza nuova "\' + nome + \'" (finestrella)\' };\n    }\n    const voce = [...pop.querySelectorAll(\'button, [role="menuitem"], [role="option"], li, a\')].filter(vis).find(e => norm(e.innerText) === norm(nome));\n    if (voce) { clic(voce); return { ok: true, come: \'licenza "\' + nome + \'" (finestrella)\' }; }\n    return { ok: false, errore: \'non riesco a scegliere il nome della licenza\' };\n  })();\n}\n\n// Finestra "Download" di Envato (codice del sito: chunk NeueDownloadModal, controllato il 29/09/2026). Gira DENTRO la\n// pagina nascosta. Due varianti: senza progetti di licenza c\'e\' il campo "Project Name" [project-name-textfield];\n// con progetti gia\' creati c\'e\' l\'elenco (radio name="project-list-radio-button-item", value = nome del progetto), la\n// ricerca e "Create new license" [create-new-project / create-new-project-button -> create-project-modal-...].\n// Elementi gratuiti: finestra "free-item-download-modal" con [download-button]. Poi "License & download"\n// [add-download-button] e, a volte, l\'avviso del certificato [license-certificate-continue-button].\nfunction licenzaEnvato(nome) {\n  const attesa = ms => new Promise(r => setTimeout(r, ms));\n  const q = s => document.querySelector(s);\n  const aspetta = async (fn, ms) => { const fine = Date.now() + ms; for (;;) { const v = fn(); if (v) return v; if (Date.now() > fine) return null; await attesa(250); } };\n  const libero = b => b && !b.disabled && b.getAttribute(\'aria-disabled\') !== \'true\';\n  const clic = el => { try { el.scrollIntoView({ block: \'center\' }); } catch (e) { } el.click(); };\n  const scrivi = (el, v) => {\n    const d = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, \'value\');\n    el.focus(); d.set.call(el, v);\n    el.dispatchEvent(new Event(\'input\', { bubbles: true })); el.dispatchEvent(new Event(\'change\', { bubbles: true }));\n  };\n  const norm = s => String(s || \'\').normalize(\'NFC\').trim().toLowerCase();\n  const radio = () => [...document.querySelectorAll(\'input[name="project-list-radio-button-item"]\')];\n  const campoDi = id => q(\'input[data-testid="\' + id + \'"]\') || q(\'[data-testid="\' + id + \'"] input\');\n\n  return (async () => {\n    // la finestra di licenza (o quella degli elementi gratuiti, o il benvenuto dei nuovi abbonati)\n    let m = await aspetta(() => q(\'[data-testid="add-download-button"]\') || q(\'[data-testid="download-button"]\') || q(\'[data-testid="subscribed-onboarding-modal-cta"]\'), 15000);\n    if (m && m.matches(\'[data-testid="subscribed-onboarding-modal-cta"]\')) {\n      clic(m); await attesa(1200);\n      const d = await aspetta(() => q(\'[data-testid="button-download"], [data-testid="action-bar-button-download"]\'), 5000);\n      if (d && !q(\'[data-testid="add-download-button"]\')) { clic(d); }\n      m = await aspetta(() => q(\'[data-testid="add-download-button"]\') || q(\'[data-testid="download-button"]\'), 12000);\n    }\n    if (!m) return { ok: false, errore: \'la finestra di licenza non si è aperta\' };\n    // elemento gratuito: basta "Download"\n    if (!q(\'[data-testid="add-download-button"]\')) {\n      const g = await aspetta(() => libero(q(\'[data-testid="download-button"]\')) && q(\'[data-testid="download-button"]\'), 8000);\n      if (!g) return { ok: false, errore: \'il bottone Download non si attiva\' };\n      clic(g); return { ok: true, come: \'elemento gratuito\' };\n    }\n    let come = \'\';\n    const campo = campoDi(\'project-name-textfield\') || q(\'input#project-name\');\n    if (campo) {                                              // primo progetto di licenza: si scrive il nome\n      scrivi(campo, nome); await attesa(500); come = \'nuovo progetto (campo)\';\n    } else {\n      let scelto = radio().find(r => norm(r.value) === norm(nome));\n      if (!scelto) {                                          // si cerca il nome nell\'elenco\n        const cerca = q(\'input[data-testid="simple-search-box-form-input"]\');\n        if (cerca) { scrivi(cerca, nome); await attesa(900); scelto = radio().find(r => norm(r.value) === norm(nome)); }\n      }\n      if (scelto) { if (!scelto.checked) clic(scelto); await attesa(400); come = \'progetto esistente\'; }\n      else {                                                  // non c\'e\': si crea la licenza col nome del lavoro\n        const crea = await aspetta(() => q(\'[data-testid="create-new-project"]\') || q(\'[data-testid="create-new-project-button"]\'), 4000);\n        if (!crea) return { ok: false, errore: \'non trovo "Create new license"\' };\n        clic(crea);\n        const c2 = await aspetta(() => campoDi(\'create-project-modal-project-name-textfield\'), 5000);\n        if (c2) {\n          scrivi(c2, nome); await attesa(400);\n          const ok = await aspetta(() => libero(q(\'[data-testid="add-project-submit-button"]\')) && q(\'[data-testid="add-project-submit-button"]\'), 5000);\n          if (!ok) return { ok: false, errore: \'non riesco a creare il progetto di licenza\' };\n          clic(ok);\n        }\n        const s2 = await aspetta(() => radio().find(r => norm(r.value) === norm(nome)), 8000);\n        if (s2 && !s2.checked) { clic(s2); await attesa(400); }\n        come = \'nuovo progetto (elenco)\';\n      }\n    }\n    const b = await aspetta(() => libero(q(\'[data-testid="add-download-button"]\')) && q(\'[data-testid="add-download-button"]\'), 10000);\n    if (!b) return { ok: false, errore: \'"License & download" non si attiva\' };\n    clic(b);\n    const avviso = await aspetta(() => q(\'[data-testid="license-certificate-continue-button"]\'), 4000);\n    if (avviso) clic(avviso);\n    return { ok: true, come };\n  })();\n}\n\nreturn await scaricaEnvato(projectName, licenzaEnvato);\n})'
